#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_N 200005

typedef struct {
    int y;
    int almonds;
    long long prefix_sum;
} CutPoint;

int compare(const void *a, const void *b) {
    return ((CutPoint*)a)->y - ((CutPoint*)b)->y;
}

int main() {
    int w, h, n, s;
    scanf("%d %d %d %d", &w, &h, &n, &s);

    CutPoint points[MAX_N];
    points[0].y = 0;
    points[0].almonds = 0;

    for (int i = 1; i <= n; i++) {
        scanf("%d %d", &points[i].y, &points[i].almonds);
    }

    // Sort by y coordinate
    qsort(points + 1, n, sizeof(CutPoint), compare);

    // Calculate prefix sums
    points[0].prefix_sum = 0;
    for (int i = 1; i <= n; i++) {
        points[i].prefix_sum = points[i-1].prefix_sum + points[i].almonds;
    }

    int min_almonds = INT_MAX;

    // Try all possible left cut positions
    for (int left = 0; left <= n; left++) {
        // Binary search for right cut position that gives area >= S
        int low = left + 1, high = n + 1;
        int found = 0;

        while (low <= high) {
            int mid = (low + high) / 2;
            int right = mid;

            // Calculate area: width * (y_right - y_left)
            long long area = (long long)w * (points[right].y - points[left].y);

            if (area >= s) {
                found = 1;
                // Calculate almonds for Be-ko's piece
                int almonds = points[right].prefix_sum - points[left].prefix_sum;
                if (almonds < min_almonds) {
                    min_almonds = almonds;
                }
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
    }

    printf("%d\n", min_almonds);

    return 0;
}

