int main() {
    int w, h, n, m;
    double S;
    scanf("%d %d %d %d %lf", &w, &h, &n, &m, &S);

    // n cuts, each: lx ly rx ry but lx=0, rx=w always
    // Store as (ly, ry) pairs, sorted
    double *ly = malloc((n+2)*sizeof(double));
    double *ry = malloc((n+2)*sizeof(double));
    // boundary cuts
    ly[0] = 0; ry[0] = 0;
    for(int i = 1; i <= n; i++) {
        scanf("%lf %lf", &ly[i], &ry[i]);
    }
    ly[n+1] = h; ry[n+1] = h;

    // m almonds at integer points
    int *ax = malloc(m*sizeof(int));
    int *ay = malloc(m*sizeof(int));
    for(int i = 0; i < m; i++) scanf("%d %d", &ax[i], &ay[i]);

    int num_slices = n+1;
    double *area = calloc(num_slices, sizeof(double));
    int *almonds = calloc(num_slices, sizeof(int));

    for(int i = 0; i < num_slices; i++) {
        area[i] = w * ((ly[i+1]-ly[i]) + (ry[i+1]-ry[i])) / 2.0;
    }

    for(int k = 0; k < m; k++) {
        // binary search for slice
        // cut i at x: ly[i] + (ry[i]-ly[i])*ax[k]/w
        // find slice where almond is above cut i and below cut i+1
        for(int i = 0; i < num_slices; i++) {
            double bot = ly[i] + (ry[i]-ly[i])*(double)ax[k]/w;
            double top = ly[i+1] + (ry[i+1]-ly[i+1])*(double)ax[k]/w;
            if(ay[k] > bot && ay[k] < top) { almonds[i]++; break; }
        }
    }

    // sliding window
    // ... find min almonds with sum area >= S
    // use two pointers
    long long best = 1e18;
    double sumA = 0; long long sumAlm = 0;
    int left = 0;
    for(int right = 0; right < num_slices; right++) {
        sumA += area[right]; sumAlm += almonds[right];
        while(sumA - area[left] >= S) { sumA -= area[left]; sumAlm -= almonds[left]; left++; }
        if(sumA >= S && sumAlm < best) best = sumAlm;
    }
    printf("%lld\n", best);
    return 0;
}

