typedef long long ll;

typedef struct {
    ll y1, y2;
} Seg;

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int cmp_seg(const void *a, const void *b) {
    const Seg *s1 = (const Seg *)a;
    const Seg *s2 = (const Seg *)b;
    if (s1->y1 != s2->y1) return (s1->y1 < s2->y1) ? -1 : 1;
    if (s1->y2 != s2->y2) return (s1->y2 < s2->y2) ? -1 : 1;
    return 0;
}

static ll *ys = NULL;
static int ycnt = 0;

int get_id(ll y) {
    int l = 0, r = ycnt - 1;
    while (l <= r) {
        int m = (l + r) >> 1;
        if (ys[m] == y) return m;
        if (ys[m] < y) l = m + 1;
        else r = m - 1;
    }
    return -1;
}

int main(void) {
    int n, m;
    ll w, h, S;
    if (scanf("%d %d %lld %lld %lld", &n, &m, &w, &h, &S) != 5) return 0;

    ll *ax = (ll *)malloc(sizeof(ll) * n);
    ll *ay = (ll *)malloc(sizeof(ll) * n);
    for (int i = 0; i < n; i++) scanf("%lld %lld", &ax[i], &ay[i]);

    Seg *cuts = (Seg *)malloc(sizeof(Seg) * m);
    ys = (ll *)malloc(sizeof(ll) * (2 * m + 2));
    int p = 0;
    ys[p++] = 0;
    ys[p++] = h;

    for (int i = 0; i < m; i++) {
        ll l, r;
        scanf("%lld %lld", &l, &r);
        if (l > r) {
            ll t = l; l = r; r = t;
        }
        cuts[i].y1 = l;
        cuts[i].y2 = r;
        ys[p++] = l;
        ys[p++] = r;
    }

    qsort(ys, p, sizeof(ll), cmp_ll);
    ycnt = 0;
    for (int i = 0; i < p; i++) {
        if (i == 0 || ys[i] != ys[i - 1]) ys[ycnt++] = ys[i];
    }

    int segN = ycnt - 1;

    int *blocked = (int *)calloc(segN, sizeof(int));

    qsort(cuts, m, sizeof(Seg), cmp_seg);
    for (int i = 0; i < m; i++) {
        int a = get_id(cuts[i].y1);
        int b = get_id(cuts[i].y2);
        for (int j = a; j < b; j++) blocked[j] = 1;
    }

    ll *alm = (ll *)calloc(segN, sizeof(ll));
    for (int i = 0; i < n; i++) {
        int id = get_id(ay[i]);
        if (id < 0) continue;
        if (id == ycnt - 1) id--;
        else if (!(ys[id] <= ay[i] && ay[i] < ys[id + 1])) id--;
        if (id >= 0 && id < segN) alm[id]++;
    }

    ll ans = -1;
    int i = 0;
    while (i < segN) {
        while (i < segN && blocked[i]) i++;
        if (i >= segN) break;
        int j = i;
        while (j < segN && !blocked[j]) j++;

        int len = j - i;
        ll *prefA = (ll *)malloc(sizeof(ll) * (len + 1));
        ll *prefH = (ll *)malloc(sizeof(ll) * (len + 1));
        prefA[0] = 0;
        prefH[0] = 0;
        for (int k = 0; k < len; k++) {
            prefA[k + 1] = prefA[k] + alm[i + k];
            prefH[k + 1] = prefH[k] + (ys[i + k + 1] - ys[i + k]);
        }

        int r = 0;
        for (int l = 0; l < len; l++) {
            if (r < l) r = l;
            while (r < len && w * (prefH[r + 1] - prefH[l]) < S) r++;
            if (r < len) {
                ll almonds = prefA[r + 1] - prefA[l];
                if (ans == -1 || almonds < ans) ans = almonds;
            }
        }

        free(prefA);
        free(prefH);
        i = j;
    }

    printf("%lld\n", ans);

    free(ax);
    free(ay);
    free(cuts);
    free(ys);
    free(blocked);
    free(alm);

    return 0;
}

