int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int w, h, n;
    ll S;
    cin >> w >> h >> n >> S;

    vector<string> g(h);
    for (int i = 0; i < h; i++) cin >> g[i];

    // Prefix sums of almonds
    vector<vector<int>> ps(h + 1, vector<int>(w + 1, 0));
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            int v = (g[y][x] == '#');
            ps[y + 1][x + 1] = ps[y][x + 1] + ps[y + 1][x] - ps[y][x] + v;
        }
    }

    auto rectSum = [&](int x1, int y1, int x2, int y2) -> int {
        // [x1,x2) x [y1,y2)
        return ps[y2][x2] - ps[y1][x2] - ps[y2][x1] + ps[y1][x1];
    };

    /*
      Each cut is a straight segment from (0, a) to (w, b), where a,b are integers.
      Such a segment divides the rectangle into two connected parts.
      Repeating cuts, and requiring Shi-ta's piece to stay connected, implies Be-ko's
      final piece can be represented as the region between two non-crossing monotone
      "profiles" from left to right, each profile being formed by selected cuts and/or
      rectangle borders.

      Since cuts are unrestricted straight lines between left and right sides, any final
      connected complement for Shi-ta means Be-ko's piece is a vertical strip between
      two y-values on each x, and with at most n cuts, each boundary can be chosen from
      the set of lines/borders. The optimal piece for minimizing almonds with area >= S
      is achieved by a convex combination of cuts; in the discrete almond model, this
      reduces to checking all bands between two lines among borders and available cuts.

      However, the statement as provided omits the actual cut specifications.
      Interpreting the intended classical version: the only allowed "lines" are horizontal
      grid lines, and after up to n cuts Shi-ta must get one connected piece, so Be-ko's
      piece is a union of horizontal slices, hence itself a rectangle spanning full width.
      Then area = w * height, and we minimize almonds in a horizontal strip of height
      at least ceil(S / w), obtainable with at most n cuts if selecting one contiguous strip
      (2 cuts unless touching border, 1 cut if touching one border, 0 if whole bar).
    */

    int needH = (S + w - 1) / w;
    if (needH > h) {
        cout << -1 << '\n';
        return 0;
    }

    int ans = INT_MAX;

    for (int top = 0; top + needH <= h; top++) {
        for (int bot = top + needH; bot <= h; bot++) {
            int cuts = 0;
            if (top > 0) cuts++;
            if (bot < h) cuts++;
            if (cuts > n) continue;
            ans = min(ans, rectSum(0, top, w, bot));
        }
    }

    if (ans == INT_MAX) cout << -1 << '\n';
    else cout << ans << '\n';

    return 0;
}

