public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int w = Integer.parseInt(st.nextToken());
        int h = Integer.parseInt(st.nextToken());
        int n = Integer.parseInt(st.nextToken());
        long S = Long.parseLong(st.nextToken());

        int[] y = new int[n];
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            y[i] = Integer.parseInt(st.nextToken());
            a[i] = Integer.parseInt(st.nextToken());
        }

        // 2D prefix sum over almonds
        // We have n horizontal strips between y[i] and y[i+1], with almonds a[i]
        // For any vertical cut at x, we can compute prefix sums of areas and almonds

        long[] prefArea = new long[n];
        long[] prefAlmond = new long[n];
        for (int i = 0; i < n; i++) {
            long height = (i == n-1) ? (h - y[i]) : (y[i+1] - y[i]);
            long area = height * w;
            prefArea[i] = (i > 0 ? prefArea[i-1] : 0) + area;
            prefAlmond[i] = (i > 0 ? prefAlmond[i-1] : 0) + a[i];
        }

        long totalArea = prefArea[n-1];
        long totalAlmond = prefAlmond[n-1];

        // Binary search on answer: minimum almonds for Be-ko
        long lo = 0, hi = totalAlmond;
        long ans = totalAlmond;

        while (lo <= hi) {
            long mid = (lo + hi) / 2;
            if (can(mid, prefArea, prefAlmond, totalArea, S, n, w)) {
                ans = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }

        System.out.println(ans);
    }

    static boolean can(long maxAlmond, long[] prefArea, long[] prefAlmond, 
                       long totalArea, long minArea, int n, int w) {
        // Check if we can give Be-ko a piece with almonds <= maxAlmond and area >= minArea
        // by choosing a contiguous set of strips from i to j (full width)
        // or by taking part of a strip (vertical cut)

        // Case 1: full strips
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                long area = prefArea[j] - (i > 0 ? prefArea[i-1] : 0);
                long almond = prefAlmond[j] - (i > 0 ? prefAlmond[i-1] : 0);
                if (area >= minArea && almond <= maxAlmond) return true;
                if (area >= minArea) break; // larger area only increases almonds
            }
        }

        // Case 2: partial strip at the top or bottom (vertical cut)
        // For each strip, we can take a vertical segment of width x (0 <= x <= w)
        // Area = height * x, Almonds = (a[i] / w) * x = (a[i] * x) / w
        // We need height * x >= minArea and (a[i] * x) / w <= maxAlmond
        // => x >= ceil(minArea / height) and x <= floor(maxAlmond * w / a[i])
        for (int i = 0; i < n; i++) {
            long height = (i == n-1) ? (prefArea[i] - (i > 0 ? prefArea[i-1] : 0)) / w 
                                     : (prefArea[i] - (i > 0 ? prefArea[i-1] : 0)) / w;
            long almondCount = prefAlmond[i] - (i > 0 ? prefAlmond[i-1] : 0);
            if (almondCount == 0) {
                if (height * w >= minArea) return true;
                continue;
            }
            // Need x such that: height * x >= minArea  => x >= (minArea + height - 1) / height
            // and (almondCount * x) / w <= maxAlmond  => x <= (maxAlmond * w) / almondCount
            long minX = (minArea + height - 1) / height;
            long maxX = (maxAlmond * w) / almondCount;
            if (minX <= maxX && minX <= w) return true;
        }

        return false;
    }
}

